SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "吴徐知诰扩建金陵城，史载周围二十里。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p011·原文件第16行", "note": "原文：吴徐知诰广金陵城周围二十里。；核对说明：沿已建李昪主体；周围二十里为城周不是增加面积二十平方里，未换现代里程或画界。", "status": "draft", "id": "87d00701-6f0f-51b8-b2de-6fbb4277bf1b", "subject_id": "8247217b-83a6-5727-969f-b65b4a3ddbf1", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "932年八月本段；确日未独载", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p011·原文件第16行", "note": "原文：吴徐知诰广金陵城周围二十里。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "393f7e60-be42-529f-876d-0e2a2b11d22b", "subject_id": "8247217b-83a6-5727-969f-b65b4a3ddbf1", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李昪：扩建金陵城者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p011·原文件第16行", "note": "原文：吴徐知诰广金陵城周围二十里。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "26d1c3a2-d03c-5baf-b59d-4f3007e18601", "subject_id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李昪：扩建金陵城者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p011·原文件第16行", "note": "原文：吴徐知诰广金陵城周围二十里。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c6d11628-d967-5bd5-bbae-95188340ee65", "subject_id": "38efad5b-25cf-5312-bb07-796f1915f285", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "description", "claim_text": "通鉴追述契丹强盛后掠卢龙，常伏阎沟劫涿州输幽州粮。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：初，契丹既强，寇抄卢龙诸州皆遍，幽州城门之外，虏骑充斥。每自涿州运粮入幽州，虏多伏兵于阎沟，掠取之。；核对说明：每次为合述，不猜次数、未名统帅；虏为史文敌称不转成本站民族称号。", "status": "draft", "id": "1e8c7c1a-e3ae-5e50-808d-547677ef1823", "subject_id": "c3b051b7-5ff9-5f24-8cfb-6b0dd5f78003", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "初，追述契丹强盛以来、赵德钧修城前；各次年份未独载", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：初，契丹既强，寇抄卢龙诸州皆遍，幽州城门之外，虏骑充斥。每自涿州运粮入幽州，虏多伏兵于阎沟，掠取之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "1856cba0-7cf7-504a-829a-6e5407a9a249", "subject_id": "c3b051b7-5ff9-5f24-8cfb-6b0dd5f78003", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "description", "claim_text": "赵德钧镇幽州后城阎沟置良乡戍守，粮道稍通。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：及赵德钧为节度使，城阎沟而戍之，为良乡县，粮道稍通。；核对说明：不因所在932年条把良乡筑城强定932；稍通不等契丹掠粮彻底绝。", "status": "draft", "id": "78c1a60e-0e0b-5111-bafd-82015fe08bc1", "subject_id": "5c0c2652-ae35-52eb-9999-54dd845a338d", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "赵德钧镇幽州后、三河奏城前追叙；确年未载", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：及赵德钧为节度使，城阎沟而戍之，为良乡县，粮道稍通。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "78485c02-e424-56c5-a166-4b43d6a3d952", "subject_id": "5c0c2652-ae35-52eb-9999-54dd845a338d", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记赵德钧：城阎沟戍守改善粮道者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：及赵德钧为节度使，城阎沟而戍之，为良乡县，粮道稍通。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "ad221085-2a69-5d7e-aa02-8f40f1463950", "subject_id": "cfda6466-f577-56a2-8851-65b57edb7d3e", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "赵德钧：城阎沟戍守改善粮道者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：及赵德钧为节度使，城阎沟而戍之，为良乡县，粮道稍通。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "928b24d4-5024-51b3-9e1e-9bdacd59eb39", "subject_id": "43adc449-bb35-5553-b01d-312d7ec91edf", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧赵传同记阎沟筑垒、戍兵守之，名良乡县以备钞寇。", "citation": "《旧五代史》卷九十八，段落 jiu-wudaishi-205deb4a7860-p002404；EPUB电子本，纸本及异文待核", "note": "原文：又於閻溝築壘，以戍兵守之，因名良鄉縣，以備鈔寇。；核对说明：旧前水运长度段属于此前运河，不在本批借其二百里覆盖主六月一百六十五里；此只取良乡城戍。", "status": "draft", "id": "9f25fd8e-1b98-516a-aa8e-dafa53e26823", "subject_id": "5c0c2652-ae35-52eb-9999-54dd845a338d", "source_id": "055dbced-4054-5ae9-a1c8-7d2d113036b3"}, {"subject_table": "event", "field_path": "description", "claim_text": "新契丹附录记于盐沟置良乡县。", "citation": "《新五代史》卷七十二，段落 xin-wudaishi-b08f244b9241-p003602；EPUB电子本，纸本及异文待核", "note": "原文：趙德鈞鎮幽州，於鹽溝置良鄉縣，；核对说明：主旧阎沟、新盐沟各字形留，不据此立两个不同县；新庄宗末表相对层次，不独定此处932。", "status": "draft", "id": "d9e82e17-1171-586e-9c8c-453a84feb318", "subject_id": "5c0c2652-ae35-52eb-9999-54dd845a338d", "source_id": "0360295c-cb40-5268-8917-cc61b35195cc"}, {"subject_table": "event", "field_path": "description", "claim_text": "赵德钧于幽州东五十里城潞县戍守，使近州民得耕作。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：幽州东十里之外，人不敢樵牧；德钧于州东五十里城潞县而戍之，近州之民始得稼穑。；核对说明：十里不能樵牧是此前安全范围，五十里为潞县相对方位；未换坐标或认现代县界。", "status": "draft", "id": "5e1678c6-e25d-59f7-99c6-30fa03d6f9dc", "subject_id": "2ad14677-d3d6-58a8-8584-b9b136e85a16", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "三河奏城前的筑城追叙；确年未载", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：幽州东十里之外，人不敢樵牧；德钧于州东五十里城潞县而戍之，近州之民始得稼穑。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b496fad6-255d-55ca-ac21-3d95935cdd86", "subject_id": "2ad14677-d3d6-58a8-8584-b9b136e85a16", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "赵德钧：幽州东城潞县戍守者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：幽州东十里之外，人不敢樵牧；德钧于州东五十里城潞县而戍之，近州之民始得稼穑。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3f1b844e-1511-5d3d-a72e-250b41792e62", "subject_id": "1e272b90-1b22-57fc-b66d-16a3b684617d", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "description", "claim_text": "新契丹附录亦记幽州东五十里筑城，戍以兵。", "citation": "《新五代史》卷七十二，段落 xin-wudaishi-b08f244b9241-p003602；EPUB电子本，纸本及异文待核", "note": "原文：又於幽州東五十里築城，皆戍以兵。；核对说明：新此句未明城名，潞县身份据主；不写新也明称潞县。", "status": "draft", "id": "bf10af9d-280a-5d97-9eb3-650e8ef91828", "subject_id": "2ad14677-d3d6-58a8-8584-b9b136e85a16", "source_id": "0360295c-cb40-5268-8917-cc61b35195cc"}, {"subject_table": "event", "field_path": "description", "claim_text": "赵德钧城三河县以通蓟州运路，并击退来争契丹骑兵。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：至是，又于州东北百馀里城三河县以通蓟州运路，虏骑来争，德钧击却之。；核对说明：百余里为相对距离，战日未独，不套后奏城庚辰；击却不等灭契丹国。", "status": "draft", "id": "095635ad-23f3-5b66-96a2-02bf5d2f1b20", "subject_id": "6b94de87-581b-5562-ad9d-7c7bb91a9b2c", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "932年八月本段；确日未独载", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：至是，又于州东北百馀里城三河县以通蓟州运路，虏骑来争，德钧击却之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c19e310c-186a-5531-b3b9-4341e88c7343", "subject_id": "6b94de87-581b-5562-ad9d-7c7bb91a9b2c", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "赵德钧：三河筑城及击却争城骑兵者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：至是，又于州东北百馀里城三河县以通蓟州运路，虏骑来争，德钧击却之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "39e902cb-ae08-5ea1-b52b-3936a070fcae", "subject_id": "7b7b01a4-0744-5068-bfc0-1be02eb9489f", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧赵传记幽州东筑三河城，北接蓟州，部民稍得樵牧。", "citation": "《旧五代史》卷九十八，段落 jiu-wudaishi-205deb4a7860-p002404；EPUB电子本，纸本及异文待核", "note": "原文：又於幽州東築三河城，北接薊州，頗為形勝之要，部民由是稍得樵牧。；核对说明：旧传概述与主东北百余里详述分层，不改主方位为正东坐标；后清泰三年带兵与夹注辽史不在本批新增。", "status": "draft", "id": "77153fd7-81e0-51dd-aff4-a75c08328839", "subject_id": "6b94de87-581b-5562-ad9d-7c7bb91a9b2c", "source_id": "055dbced-4054-5ae9-a1c8-7d2d113036b3"}, {"subject_table": "event", "field_path": "description", "claim_text": "九月庚辰朔赵德钧奏报三河城建成。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：九月，庚辰朔，奏城三河毕。边人赖之。；核对说明：奏日非必确完工日，边人赖之为史评价，不据此画全国安定。", "status": "draft", "id": "e6873c2d-f266-5ba7-89bf-f57e7c1a9f5d", "subject_id": "f0c9967b-262c-54c5-ac48-6a434cd52203", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "932年九月庚辰朔奏闻；完工具体日未独载", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：九月，庚辰朔，奏城三河毕。边人赖之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "29074057-9b8b-5cb0-b3ba-cc0445f594fe", "subject_id": "f0c9967b-262c-54c5-ac48-6a434cd52203", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "赵德钧：奏城三河毕者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p012·原文件第17行", "note": "原文：九月，庚辰朔，奏城三河毕。边人赖之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "72740fd6-8693-5472-90f2-ce85c72826af", "subject_id": "7435b5cf-c9ca-5a58-a62b-6acadf5bd52d", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "description", "claim_text": "九月壬午马希范任武安节度使，兼侍中。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p013·原文件第18行", "note": "原文：壬午，以镇南节度使马希范为武安节度使，兼侍中。；核对说明：朝廷授任与此前七月迎、八月长沙袭位分。", "status": "draft", "id": "f972f26a-a82b-5c06-881e-ae4a644f5914", "subject_id": "3a6ef637-286f-5fd6-b541-afd85cb68445", "source_id": "7713f2af-ff3e-51fc-b572-5e47bf034531"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "932年九月壬午", "citati